n;display:flex;flex-direction:column;gap:8px}\n\n.adj{display:flex;flex-direction:column;gap:10px}\n.card[data-size=\"6x3\"] .adj,.card[data-size=\"6x6\"] .adj{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:8px 14px;align-items:start}\n.card[data-size=\"6x3\"] .more,.card[data-size=\"6x6\"] .more{grid-column:1/-1}\n.now{display:flex;align-items:baseline;flex-wrap:wrap;gap:2px 6px;min-width:0}\n.now b{font-size:30px;line-height:1.05;font-variant-numeric:tabular-nums;max-width:100%;overflow:hidden;text-overflow:ellipsis}\n.card[data-size=\"3x3\"] .now b{font-size:24px}\n.now .u{color:var(--muted);font-size:13px}\n.now .line{flex-basis:100%;font-size:11px;color:var(--muted)}\n.now .line.hot{color:var(--ink);font-weight:700}\n.ctrl{display:flex;flex-direction:column;gap:8px;min-width:0}\n.more{display:flex;flex-direction:column;gap:6px}\n.ask{font-size:12px}\n\n.field{display:flex;flex-direction:column;gap:3px;font-size:11px;color:var(--muted);min-width:0}\n.field small{font-size:10px;color:var(--muted);opacity:.9}\n.field input{width:100%;min-width:0;height:32px;padding:0 8px;border:1px solid var(--line);border-radius:8px;background:var(--panel-paper);color:var(--ink);font:inherit;font-size:14px}\n.field input:focus{outline:2px solid var(--accent);outline-offset:0}\n.fgroup{display:flex;flex-direction:column;gap:5px;min-width:0}\n.fields{display:grid;grid-template-columns:minmax(0,1fr);gap:8px}\n.card[data-size=\"6x3\"] .fields,.card[data-size=\"6x6\"] .fields{grid-template-columns:repeat(2,minmax(0,1fr))}\n.chips{display:flex;flex-wrap:wrap;gap:4px}\n.chip{padding:2px 9px!important;border-radius:11px;border:1px solid var(--line)!important;font-size:11.5px;background:var(--button-paper,var(--paper))!important}\n.chip.on{background:var(--soft)!important;border-color:var(--accent)!important;font-weight:700}\n\n.btns{display:grid;grid-template-columns:1fr 1fr;gap:6px}\n.btn{min-width:0;height:34px;padding:0 8px!important;border-radius:10px;border:1px s