// 宝宝用品库存：items=[{id,name,qty,unit,low,step}]，low=null 表示未设提醒线
const LISTUI = {view:'list',id:null,draft:null,err:'',msg:'',amt:null,confirm:false,saving:false};

function r3(n){return Math.round(n*1000)/1000}
function fmt(n){return String(r3(Number(n)||0))}
function num(v){
  const t=String(v==null?'':v).trim();
  if(t==='')return null;
  const n=Number(t);
  return isFinite(n)?n:NaN;
}

function norm(s){
  const items=Array.isArray(s&&s.items)?s.items:[];
  return Object.assign({},s,{items:items.map(function(it){
    const q=Number(it.qty);
    const l=(it.low===null||it.low===undefined||it.low==='')?null:Number(it.low);
    const st=Number(it.step);
    return Object.assign({},it,{
      id:it.id,
      name:String(it.name||'未命名'),
      qty:isFinite(q)&&q>0?q:0,
      unit:String(it.unit||''),
      low:(l!==null&&isFinite(l)&&l>=0)?l:null,
      step:(isFinite(st)&&st>0)?st:1
    });
  })});
}

// 只有用户明确提到的三个名称作为空白条目预置，数量/单位/提醒线都由用户自己填
function initialize(s){
  if(s&&Array.isArray(s.items))return s;
  const mk=function(id,name){return {id:id,name:name,qty:0,unit:'',low:null,step:1}};
  return Object.assign({},s,{items:[mk('seed-diaper','尿不湿'),mk('seed-formula','奶粉'),mk('seed-wipes','湿巾')]});
}

function isLow(it){return it.low!==null&&it.qty<it.low}

// 低于提醒线的排前面（越缺越靠前），其余保持添加顺序
function sorted(items){
  return items.map(function(it,i){return {it:it,i:i}}).sort(function(a,b){
    const la=isLow(a.it),lb=isLow(b.it);
    if(la!==lb)return la?-1:1;
    if(la){
      const ra=a.it.low>0?a.it.qty/a.it.low:0;
      const rb=b.it.low>0?b.it.qty/b.it.low:0;
      if(ra!==rb)return ra-rb;
    }
    return a.i-b.i;
  }).map(function(x){return x.it});
}

function checkDraft(d){
  const name=String(d.name||'').trim();
  if(!name)return '请填写名称';
  let qty=num(d.qty);
  if(qty===null)qty=0;
  if(isNaN(qty)||qty<0)return '现有数量请填 0 或更大的数字';
  const low=num(d.low);
  if(low!==null&&(isNaN(low)||low<0))return '提醒线请填 0 或更大的数字，或留空';
  const step=num(d.step);
  if(step===null||isNaN(step)||step<=0)return '每次加减请填大于 0 的数字';
  return {name:name,qty:r3(qty),unit:String(d.unit||'').trim(),low:low===null?null:r3(low),step:r3(step)};
}


function mount(ctx){
  const {root,el,state,ui,update,commit,redraw,uid,percent}=ctx;
  const items=norm(state).items;

  function find(id){return items.find(function(x){return x.id===id})}
  function nav(view,id,draft){
    ui.view=view;ui.id=id||null;ui.draft=draft||null;
    ui.err='';ui.msg='';ui.amt=null;ui.confirm=false;ui.saving=false;
    redraw();
  }
  function fail(e){
    ui.err='保存失败：'+((e&&e.message)||'请重试');
    ui.saving=false;
    redraw();
  }
  function draftOf(it){
    return {name:it.name,qty:fmt(it.qty),unit:it.unit,low:it.low===null?'':fmt(it.low),step:fmt(it.step)};
  }
  function openAdd(){nav('form',null,{name:'',qty:'',unit:'',low:'',step:'1'})}

  // 行内 −/＋：按该物品自己的“每次加减”步长，基于最新数据修改
  function bump(id,dir){
    update(function(s){
      const n=norm(s);
      return Object.assign({},n,{items:n.items.map(function(it){
        return it.id===id?Object.assign({},it,{qty:Math.max(0,r3(it.qty+dir*it.step))}):it;
      })});
    }).catch(fail);
  }

  function head(){
    const lowN=items.filter(isLow).length;
    const sum=lowN?('! '+lowN+' 样快用完'):(items.length?'都还够用':'还没有物品');
    return el('div',{class:'head'},
      el('div',{class:'title'},
        el('b',{},'宝宝库存'),
        el('span',{class:'sum'+(lowN?' warn':'')},sum)),
      el('button',{class:'add',type:'button','aria-label':'添加物品',onclick:openAdd},
        '＋',el('span',{class:'txt'},'添加')));
  }

  function subText(it){
    if(it.low===null)return '未设提醒线';
    return isLow(it)?'! 快用完':('提醒线 '+fmt(it.low));
  }

  function row(it){
    const low=isLow(it);
    const open=function(){nav('adjust',it.id)};
    const r=el('div',{class:'row'+(low?' low':'')},
      el('button',{class:'info',type:'button',onclick:open},
        el('span',{class:'nm'},it.name),
        el('span',{class:'sub'},subText(it))),
      el('div',{class:'step'},
        el('button',{class:'sb',type:'button','aria-label':it.name+' 用掉 '+fmt(it.step),disabled:it.qty<=0,onclick:function(){bump(it.id,-1)}},'−'),
        el('button',{class:'qty',type:'button','aria-label':it.name+' 剩 '+fmt(it.qty)+it.unit+'，点开调整',onclick:open},
          el('b',{},fmt(it.qty)),
          el('i',{},it.unit)),
        el('button',{class:'sb',type:'button','aria-label':it.name+' 买来 '+fmt(it.step),onclick:function(){bump(it.id,1)}},'＋')));
    if(it.low!==null&&it.low>0){
      r.appendChild(el('div',{class:'bar'},
        el('span',{style:'width:'+percent(Math.min(it.qty,it.low*2),it.low*2)+'%'},''),
        el('em',{},'')));
    }
    return r;
  }

  function renderList(){
    const kids=[head()];
    if(ui.err)kids.push(el('div',{class:'err'},'⚠ '+ui.err));
    if(!items.length){
      kids.push(el('div',{class:'empty'},
        el('p',{},'还没有物品'),
        el('button',{class:'btn primary',type:'button',onclick:openAdd},'＋ 添加第一样')));
      return kids;
    }
    const list=el('div',{class:'list',onscroll:function(e){ui.scrollTop=e.target.scrollTop}});
    sorted(items).forEach(function(it){list.appendChild(row(it))});
    kids.push(list);
    kids.listEl=list;
    return kids;
  }


  function subHead(title,onBack){
    return el('div',{class:'sub-head'},
      el('button',{class:'back',type:'button',onclick:onBack},'‹ 返回'),
      el('b',{},title));
  }

  // 用掉 / 买来：输入数量后减或加；成功后回到列表，能看到重新排序后的结果
  function renderAdjust(){
    const it=find(ui.id);
    if(!it){ui.view='list';return renderList()}
    const amt=ui.amt==null?fmt(it.step):ui.amt;
    function doAdjust(dir){
      if(ui.saving)return;
      const a=num(ui.amt==null?fmt(it.step):ui.amt);
      if(a===null||isNaN(a)||a<=0){ui.err='请填写大于 0 的数量';redraw();return}
      if(dir<0&&a>it.qty){ui.err='只剩 '+fmt(it.qty)+it.unit+'，不够用掉 '+fmt(a);redraw();return}
      ui.saving=true;
      commit(function(s){
        const n=norm(s);
        return Object.assign({},n,{items:n.items.map(function(x){
          return x.id===it.id?Object.assign({},x,{qty:Math.max(0,r3(x.qty+dir*a))}):x;
        })});
      },LISTUI).catch(fail);
    }
    function doDelete(){
      if(ui.saving)return;
      ui.saving=true;
      commit(function(s){
        const n=norm(s);
        return Object.assign({},n,{items:n.items.filter(function(x){return x.id!==it.id})});
      },LISTUI).catch(fail);
    }
    const input=el('input',{type:'number',value:amt,placeholder:'数量','aria-label':'数量',
      oninput:function(e){ui.amt=e.target.value},
      onkeydown:function(e){if(e.key==='Enter')doAdjust(1)}});
    input.setAttribute('inputmode','decimal');
    input.setAttribute('min','0');
    input.setAttribute('step','any');
    const lineTxt=it.low===null?'还没设提醒线':('低于 '+fmt(it.low)+it.unit+' 会排到最前');
    const more=ui.confirm
      ?el('div',{class:'more'},
          el('span',{class:'ask'},'确定删除「'+it.name+'」？'),
          el('div',{class:'btns'},
            el('button',{class:'btn strong',type:'button',onclick:doDelete},'确认删除'),
            el('button',{class:'btn',type:'button',onclick:function(){ui.confirm=false;redraw()}},'取消')))
      :el('div',{class:'more'},
          el('div',{class:'btns'},
            el('button',{class:'btn',type:'button',onclick:function(){nav('form',it.id,draftOf(it))}},'编辑信息'),
            el('button',{class:'btn',type:'button',onclick:function(){ui.confirm=true;redraw()}},'删除')));
    const body=el('div',{class:'body'},
      el('div',{class:'adj'},
        el('div',{class:'now'},
          el('b',{},fmt(it.qty)),
          el('span',{class:'u'},it.unit||'（未填单位）'),
          el('span',{class:'line'+(isLow(it)?' hot':'')},(isLow(it)?'! 快用完 · ':'')+lineTxt)),
        el('div',{class:'ctrl'},
          el('label',{class:'field'},el('span',{},'这次数量'+(it.unit?'（'+it.unit+'）':'')),input),
          el('div',{class:'btns'},
            el('button',{class:'btn',type:'button',onclick:function(){doAdjust(-1)}},'− 用掉'),
            el('button',{class:'btn primary',type:'button',onclick:function(){doAdjust(1)}},'＋ 买来')),
          ui.err?el('div',{class:'err'},'⚠ '+ui.err):el('span',{},'')),
        more));
    return [subHead(it.name,function(){nav('list')}),body];
  }

  // 新增 / 编辑共用表单
  function renderForm(){
    if(!ui.draft)ui.draft={name:'',qty:'',unit:'',low:'',step:'1'};
    const d=ui.draft;
    const isNew=!ui.id;
    function save(){
      if(ui.saving)return;
      const r=checkDraft(d);
      if(typeof r==='string'){ui.err=r;redraw();return}
      ui.saving=true;
      const id=isNew?uid():ui.id;
      commit(function(s){
        const n=norm(s);
        const list=isNew
          ?n.items.concat([Object.assign({id:id},r)])
          :n.items.map(function(x){return x.id===id?Object.assign({},x,r):x});
        return Object.assign({},n,{items:list});
      },LISTUI).catch(fail);
    }
    function field(key,label,hint,isNum){
      const inp=el('input',{type:isNum?'number':'text',value:d[key]==null?'':String(d[key]),'aria-label':label,
        oninput:function(e){d[key]=e.target.value},
        onkeydown:function(e){if(e.key==='Enter')save()}});
      if(isNum){inp.setAttribute('inputmode','decimal');inp.setAttribute('min','0');inp.setAttribute('step','any')}
      const kids=[el('span',{},label),inp];
      if(hint)kids.push(el('small',{},hint));
      return el('label',{class:'field'},...kids);
    }
    const chips=el('div',{class:'chips'});
    ['片','包','罐','袋','盒'].forEach(function(c){
      chips.appendChild(el('button',{class:'chip'+(d.unit===c?' on':''),type:'button',onclick:function(){d.unit=c;redraw()}},c));
    });
    const body=el('div',{class:'body'},
      el('div',{class:'fields'},
        field('name','名称','例如 尿不湿'),
        field('qty','现有数量','留空按 0',true),
        el('div',{class:'fgroup'},field('unit','单位','自己填，或点下面常用的'),chips),
        field('low','快用完提醒线','数量低于它时排到最前，留空不提醒',true),
        field('step','每次加减','列表里 − / ＋ 一次变多少',true)),
      ui.err?el('div',{class:'err'},'⚠ '+ui.err):el('span',{},''),
      el('div',{class:'btns'},
        el('button',{class:'btn',type:'button',onclick:function(){isNew?nav('list'):nav('adjust',ui.id)}},'取消'),
        el('button',{class:'btn primary',type:'button',onclick:save},isNew?'添加':'保存')));
    return [subHead(isNew?'添加物品':'编辑物品',function(){isNew?nav('list'):nav('adjust',ui.id)}),body];
  }

  const v=ui.view||'list';
  const kids=v==='adjust'?renderAdjust():v==='form'?renderForm():renderList();
  kids.forEach(function(k){root.appendChild(k)});
  if(kids.listEl&&ui.scrollTop)kids.listEl.scrollTop=ui.scrollTop;
}

